text:
{{
  (() => {
    const placa = String(inpCpPlaca.text || "").trim();
    const vehiculo = qCpBuscarVehiculoPorPlaca.data?.[0];

    if (!placa) return "";

    if (!vehiculo?.vehiculo_id) {
      return "⚪ VEHÍCULO NUEVO";
    }

    const dias = Number(vehiculo.dias_vigencia_soat);

    if (
      vehiculo.identidad_activa === false ||
      vehiculo.relacion_activa === false ||
      vehiculo.estado_administrativo !== "ACTIVO"
    ) {
      return "🔴 VEHÍCULO INACTIVO";
    }

    if (vehiculo.disponible_para_viaje === false) {
      return "🔴 VEHICULO NO APTO PARA VIAJE";
    }

    if (Number.isFinite(dias) && dias < 0) {
      return `🔴 SOAT VENCIDO HACE ${Math.abs(dias)} ${
        Math.abs(dias) === 1 ? "DÍA" : "DÍAS"
      }`;
    }

    if (dias === 0) {
      return "🟠 SOAT VENCE HOY";
    }

    if (dias === 1) {
      return "🟠 SOAT VENCE MAÑANA";
    }

    if (Number.isFinite(dias) && dias <= 30) {
      return `🟠 SOAT VENCE EN ${dias} DÍAS`;
    }

    if (Number.isFinite(dias) && dias <= 90) {
      return `🟡 SOAT VENCE EN ${dias} DÍAS`;
    }

    return "🟢 VEHICULO APTO PARA VIAJE";
  })()
}}

textColor:
{{
  (() => {
    const placa = String(inpCpPlaca.text || "").trim();
    const vehiculo = qCpBuscarVehiculoPorPlaca.data?.[0];

    if (!placa || !vehiculo?.vehiculo_id) {
      return "#5F6368";
    }

    const dias = Number(vehiculo.dias_vigencia_soat);

    if (
      vehiculo.identidad_activa === false ||
      vehiculo.relacion_activa === false ||
      vehiculo.estado_administrativo !== "ACTIVO" ||
      vehiculo.disponible_para_viaje === false ||
      (Number.isFinite(dias) && dias < 0)
    ) {
      return "#C62828";
    }

    if (Number.isFinite(dias) && dias <= 30) {
      return "#E65100";
    }

    if (Number.isFinite(dias) && dias <= 90) {
      return "#9A6700";
    }

    return "#2E7D32";
  })()
}}
